{"command":"python3 - <<'EOF'
import re
from pathlib import Path

def extract(path):
    lines = Path(path).read_text().splitlines()
    for i, line in enumerate(lines):
        if line.strip() != "run: |":
            continue
        indent = len(line) - len(line.lstrip())
        body = []
        for candidate in lines[i + 1:]:
            if candidate.strip() and (len(candidate) - len(candidate.lstrip())) <= indent:
                break
            body.append(candidate)
        while body and not body[-1].strip():
            body.pop()
        block = "\n".join(body)
        if "provider_config=$(printf" in block:
            return block
    raise AssertionError("not found")

a = extract(".github/workflows/bench.yml")
b = extract(".github/workflows/bench-harbor.yml")
print("byte-identical:", a == b, "| bench lines:", len(a.splitlines()), "| harbor lines:", len(b.splitlines()))
leftover = re.findall(r"\$\{\{[^}]*\}\}", b)
print("expressions in block:", leftover)
EOF"}

